import{_ as s,l as i,o as e,c as l,v as t,p as n,x as o,d,i as h,S as c}from"./chunks/framework.InCnrqk-.js";const E=JSON.parse('{"title":"GFS / HDFS","description":"","frontmatter":{"title":"GFS / HDFS","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/gfs-hdfs.md","filePath":"cs/gfs-hdfs.md","lastUpdated":1789023840000}'),p={name:"cs/gfs-hdfs.md"};function S(f,a,m,u,_,D){const r=i("Mermaid");return e(),l("div",null,[a[1]||(a[1]=t('<h1 id="gfs-hdfs" tabindex="-1">GFS / HDFS <a class="header-anchor" href="#gfs-hdfs" aria-label="Permalink to &quot;GFS / HDFS&quot;">​</a></h1><div class="epigraph"><p>大文件切块，多副本放块服务器；主存元数据。主是 CP 小状态，数据面是尽力吞吐。客户端缓存块位置，租约管写。</p><footer>—— 据 Ghemawat, Gobioff and Leung, The Google File System, SOSP 2003；HDFS 架构（Shvachko et al., MSST 2010）整理</footer></div><p>上一课<a href="/cs/chaos-engineering">混沌</a>把崩溃当实验。GFS 把崩溃当<strong>日常设计点</strong>。缺口是<strong>大数据文件如何在普通机器上活</strong>：不是 etcd 里放 blob。本课钉主 + 块副本。后课对象存储换 API 与一致性档。不重写 Raft 日志。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>GFS：chunk 默认 64MB，三副本。Master 管命名空间与块位置，不承运数据。客户端问主拿位置，再打 chunkserver。写：主发租约给主副本，流水线推数据，主副本排序，再数据推。主故障：有 checkpoint+操作日志，早期单主切换慢——这是<a href="/cs/primary-backup-failover">主备</a>形态。</p><p>HDFS 公开实现同族：NameNode + DataNode，块报告、租约、流水线。HA NameNode 后来用共享编辑日志或独立 Journal。</p><p><span class="marginnote">SOSP 2003 强调弱一致性：追加、快照、主缓存过期。MapReduce 的输入是这种文件。本课不写 MapReduce。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>读：从最近副本读，校验和。写：租约防双写同一 chunk。主内存元数据要匹配块服务器心跳；幽灵块靠校验与扫描。</p>',9)),(e(),n(c,null,{default:o(()=>[h(r,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20C%5B%22%E5%AE%A2%E6%88%B7%E7%AB%AF%22%5D%20--%3E%20M%5B%22%E4%B8%BB%20%2F%20NameNode%22%5D%0A%20%20M%20--%3E%20LOC%5B%22%E5%9D%97%E4%BD%8D%E7%BD%AE%22%5D%0A%20%20C%20--%3E%20CS%5B%22chunkserver%20%2F%20DataNode%22%5D%0A%20%20CS%20--%3E%20REP%5B%22%E6%B5%81%E6%B0%B4%E7%BA%BF%E5%89%AF%E6%9C%AC%22%5D%0A"})]),fallback:o(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>不要把主当数据面：主过载会让整个命名空间停，尽管磁盘还在。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>一致性：GFS 对并发写不保证 POSIX 全语义，保证追加的「至少一次」类记录追加（record append）可能有填充与重复——应用要容。这与<a href="/cs/linearizability">线性一致</a>文件对象不同。HDFS 对打开写的文件限制更严。选档为吞吐。</p><p>与 Chubby：GFS 主选主可外包锁服务。与<a href="/cs/chain-replication">链式复制</a>：流水线像短链，提交规则是租约主排序。</p><p>本课不写纠删码替代三副本的全部。也不写小文件海量的 NameNode 内存墙——下一课元数据会碰。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把 Colossus 内部当公开规格。后课默认：块存储 = 小 CP 元数据 + 大数据面副本；POSIX 语义不默认。对象存储下一课把命名空间再摊平。分布式文件元数据课专门打 NameNode 墙。</p><p>数据面可丢一台；元数据面是控制面单点，必须有自己的恢复故事。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>GFS/HDFS：主管元数据，块服务器管字节，租约管写。</li><li>文件语义弱于 POSIX；为吞吐与追加。</li><li>主必须快照+日志；客户端缓存位置会过期。</li><li>出处：Ghemawat et al., SOSP 2003；Shvachko et al., MSST 2010。</li></ul>',10))])}const P=s(p,[["render",S]]);export{E as __pageData,P as default};
